CREATE FUNCTION pos_security."check_UserPermission"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $fn$
BEGIN
  IF session_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
  IF NEW."userId" IS NOT NULL AND EXISTS (SELECT 1 FROM public."User" ref WHERE ref."id" = NEW."userId" AND ref."businessId" IS DISTINCT FROM (SELECT o0."businessId" FROM public."User" o0 WHERE o0."id" = NEW."userId")) THEN RAISE EXCEPTION 'Cross-business reference rejected' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END $fn$;
REVOKE ALL ON FUNCTION pos_security."check_UserPermission"() FROM PUBLIC;
CREATE TRIGGER pos_check_references BEFORE INSERT OR UPDATE ON public."UserPermission" FOR EACH ROW EXECUTE FUNCTION pos_security."check_UserPermission"();

