ALTER TABLE public."PaymentGatewayEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PaymentGatewayEvent" FORCE ROW LEVEL SECURITY;
DO $policy$ DECLARE owner_name text; BEGIN SELECT pg_get_userbyid(relowner) INTO owner_name FROM pg_class WHERE oid='public."PaymentGatewayEvent"'::regclass; EXECUTE format('CREATE POLICY pos_system ON public."PaymentGatewayEvent" TO %I USING (true) WITH CHECK (true)', owner_name); END $policy$;
CREATE POLICY pos_tenant ON public."PaymentGatewayEvent" USING ("PaymentGatewayEvent"."businessId" = NULLIF(current_setting('pos.business_id', true), '') AND EXISTS (SELECT 1 FROM public."Business" b WHERE b.id = NULLIF(current_setting('pos.business_id', true), '') AND b."tenantId" = NULLIF(current_setting('pos.tenant_id', true), ''))) WITH CHECK ("PaymentGatewayEvent"."businessId" = NULLIF(current_setting('pos.business_id', true), '') AND EXISTS (SELECT 1 FROM public."Business" b WHERE b.id = NULLIF(current_setting('pos.business_id', true), '') AND b."tenantId" = NULLIF(current_setting('pos.tenant_id', true), '')));
CREATE FUNCTION pos_security."check_PaymentGatewayEvent"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $fn$
BEGIN
  IF session_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
  IF NEW."businessId" IS NOT NULL AND EXISTS (SELECT 1 FROM public."Business" ref WHERE ref."id" = NEW."businessId" AND ref."id" IS DISTINCT FROM NEW."businessId") THEN RAISE EXCEPTION 'Cross-business reference rejected' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END $fn$;
REVOKE ALL ON FUNCTION pos_security."check_PaymentGatewayEvent"() FROM PUBLIC;
CREATE TRIGGER pos_check_references BEFORE INSERT OR UPDATE ON public."PaymentGatewayEvent" FOR EACH ROW EXECUTE FUNCTION pos_security."check_PaymentGatewayEvent"();

COMMIT;
